import{_ as o,o as e,c as r,a2 as d}from"./chunks/framework.DCaeQ2Kp.js";const u=JSON.parse('{"title":"仓库与协作","description":"","frontmatter":{},"headers":[],"relativePath":"guide/repos.md","filePath":"guide/repos.md"}'),a={name:"guide/repos.md"};function c(l,t,m,i,s,n){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="仓库与协作" tabindex="-1">仓库与协作 <a class="header-anchor" href="#仓库与协作" aria-label="Permalink to &quot;仓库与协作&quot;">​</a></h1><p>四个独立 public 仓库，<code>master</code> 为默认分支；<code>momo/</code> 本地目录只是整合文件夹，不是 monorepo。</p><table tabindex="0"><thead><tr><th>仓库</th><th>语言</th><th>内容</th><th>CI</th></tr></thead><tbody><tr><td><a href="https://github.com/Momoyeyu/momo-docs" target="_blank" rel="noreferrer">momo-docs</a></td><td>MD</td><td>全部设计文档（权威来源）</td><td>—</td></tr><tr><td><a href="https://github.com/Momoyeyu/momo-app" target="_blank" rel="noreferrer">momo-app</a></td><td>Rust+TS</td><td><code>momod</code> 编排器 + Web 前端</td><td>fmt/clippy/test + web ✓</td></tr><tr><td><a href="https://github.com/Momoyeyu/momo-models" target="_blank" rel="noreferrer">momo-models</a></td><td>Python</td><td>ASR/TTS/embed 服务 + 训练</td><td>ruff/pytest ✓</td></tr><tr><td><a href="https://github.com/Momoyeyu/momo-infra" target="_blank" rel="noreferrer">momo-infra</a></td><td>Rust</td><td><code>momoctl</code> CLI + Web 控制台</td><td>fmt/clippy/test ✓</td></tr></tbody></table><h2 id="开发约定" tabindex="-1">开发约定 <a class="header-anchor" href="#开发约定" aria-label="Permalink to &quot;开发约定&quot;">​</a></h2><ul><li><strong>文档先行</strong>：实现与 momo-docs 不一致视为 bug，先改文档再改代码</li><li><strong>Commit</strong>：单行 <code>&lt;type&gt;: &lt;what&gt;</code>，<code>type</code> ∈ <code>feat|fix|refactor|docs|chore|test|build</code>，无 AI trailer</li><li><strong>跨平台</strong>：macOS 开发 / Linux+Windows 部署（momo-models 的 Windows 走 WSL2）；禁无条件 unix-only API，路径用 <code>PathBuf</code>/<code>path.join</code>，TLS 一律 rustls</li><li><strong>env 纪律</strong>：新增 <code>MOMO_*</code> 键同步 <code>.env.example</code> + <code>config.md</code> + 实现；敏感值永不入库</li></ul><h2 id="二次开发入口" tabindex="-1">二次开发入口 <a class="header-anchor" href="#二次开发入口" aria-label="Permalink to &quot;二次开发入口&quot;">​</a></h2><ol><li>先读 <a href="/momo/guide/architecture">总体架构</a> 与 <a href="/momo/guide/protocol">协议</a></li><li>按仓库 README 起本地环境；<code>momoctl doctor</code> 检查依赖与端点</li><li>在 <a href="https://github.com/users/Momoyeyu/projects/2" target="_blank" rel="noreferrer">Project 看板</a> 认领 issue（P0 优先）</li><li>改架构/协议/配置 → 先提 momo-docs PR</li></ol>',7)])])}const p=o(a,[["render",c]]);export{u as __pageData,p as default};
